    def get_orders(self, start, end, first_crawl, first_loop, page_token={}):
        warehouse_customer_id = self.customer_id
        orders_page_size = 100
        path = "v1/orders"
        # from date is created_date
        # get 1 day at a time since orders rsp is slow
        start_time = (
            start
            if not page_token.get("start_time")
            else str_to_dt(page_token["start_time"])
        )
        end_time = start_time + timedelta(days=1)
        page_token = page_token.get("page", 1)
        query_params = {
            "page": page_token,
            "from_date": start_time.strftime("%Y%m%d"),
            "to_date": end_time.strftime("%Y%m%d"),
        }
        order_ids = set()
        try:
            orders_response = self.excelsior_request(path, params=query_params)
        except Exception as e:
            if "NO MATCHING ORDERS FOUND" in str(e):
                orders_response = []
            else:
                raise e
        for order in orders_response:
            order = order["consumer_order"]
            order_ids.add(order["order_id"])
        # query all open orders in dynamo
        if first_loop and not first_crawl:
            order_params = {"status": {"eq": "open"}}
            order_resource = Order(self)
            open_orders = order_resource.get_all_resources(order_params)
            for order in open_orders:
                order_id = order["id"]
                if order_id in order_ids:
                    continue
                order_ids.add(order_id)
                order_path = f"{path}?order_id={order_id}"
                try:
                    order_response = self.excelsior_request(order_path)
                except Exception as e:
                    if "NO MATCHING ORDERS FOUND" in str(e):
                        logger.warning(f"Excelsior order disappeared: {order_id}")
                        continue
                    raise e
                orders_response.extend(order_response)

        formatted_orders = []
        for order in orders_response:
            order = order["consumer_order"]
            order_id = order["order_id"]
            shipments_path = f"v2/shipments?order_id={order_id}"
            try:
                shipments_response = self.excelsior_request(shipments_path)
            except Exception as e:
                if "Shipment not found or not yet COMPLETE" in str(e):
                    shipments_response = {"shipments": []}
                else:
                    raise PokedexException(
                        f"Error getting shipments for order {order_id}: {e}",
                        400,
                        origin="integration",
                    )
            order_shipments = shipments_response["shipments"]
            formatted_order = format_order(
                order, warehouse_customer_id, order_shipments
            )
            formatted_orders.append(formatted_order)

        next_token = None
        if len(orders_response) == orders_page_size:
            next_token = {
                "page": page_token + 1,
                "start_time": dt_to_str(start_time),
            }
        elif end_time < end + timedelta(days=1):  # get next day just to be safe
            next_token = {
                "page": 1,
                "start_time": dt_to_str(end_time),
            }

        return {"data": formatted_orders, "next_token": next_token}

